-- Worked example 2: y = a + b + c + d in two stages (ieee.numeric_std)
-- ports: clk; a, b, c, d : in unsigned(7 downto 0);
--        y : out unsigned(9 downto 0)
architecture rtl of sum4_pipe is
  signal s1, s2 : unsigned(8 downto 0) := (others => '0');
begin
  process (clk)
  begin
    if rising_edge(clk) then
      s1 <= resize(a, 9) + resize(b, 9);       -- stage 1
      s2 <= resize(c, 9) + resize(d, 9);       -- stage 1
      y  <= resize(s1, 10) + resize(s2, 10);   -- stage 2
    end if;
  end process;
end architecture;

